function transform(files) {
  const changed = [];

  function findMatchingBrace(s, openIndex) {
    let depth = 0;
    let inStr = null;
    let esc = false;
    let lineComment = false;
    let blockComment = false;
    for (let i = openIndex; i < s.length; i++) {
      const ch = s[i];
      const nx = s[i + 1];
      if (lineComment) {
        if (ch === '\n') lineComment = false;
        continue;
      }
      if (blockComment) {
        if (ch === '*' && nx === '/') {
          blockComment = false;
          i++;
        }
        continue;
      }
      if (inStr) {
        if (esc) esc = false;
        else if (ch === '\\') esc = true;
        else if (ch === inStr) inStr = null;
        continue;
      }
      if (ch === '/' && nx === '/') {
        lineComment = true;
        i++;
        continue;
      }
      if (ch === '/' && nx === '*') {
        blockComment = true;
        i++;
        continue;
      }
      if (ch === '"' || ch === "'" || ch === '`') {
        inStr = ch;
        continue;
      }
      if (ch === '{') depth++;
      else if (ch === '}') {
        depth--;
        if (depth === 0) return i;
      }
    }
    return -1;
  }

  function parseCreateWorld(src) {
    const re = /export\s+function\s+createWorld\s*\(\s*([A-Za-z_$][\w$]*)\s*,\s*([A-Za-z_$][\w$]*)\s*\)\s*\{/m;
    const m = re.exec(src);
    if (!m) return null;
    const braceIndex = src.indexOf('{', m.index);
    if (braceIndex < 0) return null;
    const endBrace = findMatchingBrace(src, braceIndex);
    if (endBrace < 0) return null;
    return {
      start: m.index,
      end: endBrace + 1,
      threeParam: m[1],
      sceneParam: m[2],
      body: src.slice(braceIndex + 1, endBrace)
    };
  }

  function makeWrapper(threeName, sceneName) {
    const origName = '__earlOriginalCreateWorld__';
    const stateName = '__earlInstancingState__';
    return '' +
      'function ' + origName + '(' + threeName + ', ' + sceneName + ') {' +
      '  return (function(){' +
      '    ' + '/*__EARL_ORIGINAL_BODY__*/' +
      '  }).call(this);' +
      '}\n\n' +
      'export function createWorld(' + threeName + ', ' + sceneName + ') {\n' +
      '  const __earlWorld__ = ' + origName + '(' + threeName + ', ' + sceneName + ');\n' +
      '  const ' + stateName + ' = (function() {\n' +
      '    const __MeshCtor__ = ' + threeName + ' && ' + threeName + '.Mesh;\n' +
      '    const __InstancedMeshCtor__ = ' + threeName + ' && ' + threeName + '.InstancedMesh;\n' +
      '    const __Matrix4Ctor__ = ' + threeName + ' && ' + threeName + '.Matrix4;\n' +
      '    if (!__MeshCtor__ || !__InstancedMeshCtor__ || !__Matrix4Ctor__) return null;\n' +
      '    if (!' + sceneName + ' || typeof ' + sceneName + '.traverse !== "function") return null;\n' +
      '    function __isOpaqueMaterial__(mat) {\n' +
      '      if (!mat || Array.isArray(mat)) return false;\n' +
      '      if (mat.transparent === true) return false;\n' +
      '      if (typeof mat.opacity === "number" && mat.opacity < 1) return false;\n' +
      '      if (typeof mat.alphaTest === "number" && mat.alphaTest > 0) return false;\n' +
      '      return true;\n' +
      '    }\n' +
      '    function __valueSig__(v) {\n' +
      '      if (v == null) return String(v);\n' +
      '      const t = typeof v;\n' +
      '      if (t === "number" || t === "boolean" || t === "string") return String(v);\n' +
      '      if (Array.isArray(v)) {\n' +
      '        let out = "[";\n' +
      '        for (let i = 0; i < v.length; i++) out += (i ? "," : "") + __valueSig__(v[i]);\n' +
      '        return out + "]";\n' +
      '      }\n' +
      '      if (v && typeof v.getHexString === "function") return "color:" + v.getHexString();\n' +
      '      if (v && typeof v.toArray === "function") return "arr:" + v.toArray([]).join(",");\n' +
      '      if (v && typeof v.uuid === "string" && v.constructor && v.constructor.name) return "ref:" + v.constructor.name + ":" + v.uuid;\n' +
      '      return null;\n' +
      '    }\n' +
      '    function __materialKey__(mat) {\n' +
      '      if (!mat || !mat.type) return null;\n' +
      '      const props = ["type","color","roughness","metalness","emissive","emissiveIntensity","map","normalMap","roughnessMap","metalnessMap","aoMap","side","flatShading","wireframe","vertexColors","fog","toneMapped","depthTest","depthWrite"];\n' +
      '      let out = "";\n' +
      '      for (let i = 0; i < props.length; i++) {\n' +
      '        const k = props[i];\n' +
      '        const sig = __valueSig__(mat[k]);\n' +
      '        if (sig !== null) out += k + "=" + sig + ";";\n' +
      '      }\n' +
      '      return out;\n' +
      '    }\n' +
      '    function __appendArrayData__(arr, out) {\n' +
      '      if (!arr || typeof arr.length !== "number") { out.push("na"); return; }\n' +
      '      const len = arr.length;\n' +
      '      out.push(String(len));\n' +
      '      for (let i = 0; i < len; i++) out.push(String(arr[i]));\n' +
      '    }\n' +
      '    function __geometryKey__(geo) {\n' +
      '      if (!geo || !geo.attributes) return null;\n' +
      '      const out = [String(geo.type || "Geometry")];\n' +
      '      const names = [];\n' +
      '      for (const k in geo.attributes) names.push(k);\n' +
      '      names.sort();\n' +
      '      out.push("attrs", String(names.length));\n' +
      '      for (let i = 0; i < names.length; i++) {\n' +
      '        const n = names[i];\n' +
      '        const a = geo.attributes[n];\n' +
      '        if (!a || !a.array) return null;\n' +
      '        out.push(n, String(a.itemSize), a.normalized ? "1" : "0", String(a.count), a.array && a.array.constructor ? String(a.array.constructor.name || "") : "");\n' +
      '        __appendArrayData__(a.array, out);\n' +
      '      }\n' +
      '      const idx = geo.index;\n' +
      '      if (idx) {\n' +
      '        if (!idx.array) return null;\n' +
      '        out.push("idx", String(idx.count), idx.array && idx.array.constructor ? String(idx.array.constructor.name || "") : "");\n' +
      '        __appendArrayData__(idx.array, out);\n' +
      '      } else {\n' +
      '        out.push("idx", "0");\n' +
      '      }\n' +
      '      const groups = Array.isArray(geo.groups) ? geo.groups : [];\n' +
      '      out.push("groups", String(groups.length));\n' +
      '      for (let i = 0; i < groups.length; i++) {\n' +
      '        const g = groups[i] || {};\n' +
      '        out.push(String(g.start), String(g.count), String(g.materialIndex));\n' +
      '      }\n' +
      '      return out.join("|");\n' +
      '    }\n' +
      '    const __groups__ = Object.create(null);\n' +
      '    let __nextParentId__ = 1;\n' +
      '    function __parentId__(parent) {\n' +
      '      if (!parent) return 0;\n' +
      '      if (parent.__earlInstancingParentId__ == null) parent.__earlInstancingParentId__ = __nextParentId__++;\n' +
      '      return parent.__earlInstancingParentId__;\n' +
      '    }\n' +
      '    ' + sceneName + '.updateMatrixWorld(true);\n' +
      '    ' + sceneName + '.traverse(function(__obj__) {\n' +
      '      if (!(__obj__ instanceof __MeshCtor__)) return;\n' +
      '      if (__obj__ instanceof __InstancedMeshCtor__) return;\n' +
      '      if (!__obj__.parent) return;\n' +
      '      if (!__obj__.geometry || !__isOpaqueMaterial__(__obj__.material)) return;\n' +
      '      const __gk__ = __geometryKey__(__obj__.geometry);\n' +
      '      const __mk__ = __materialKey__(__obj__.material);\n' +
      '      if (!__gk__ || !__mk__) return;\n' +
      '      const __key__ = __parentId__(__obj__.parent) + "|" + __gk__ + "|" + __mk__;\n' +
      '      let __group__ = __groups__[__key__];\n' +
      '      if (!__group__) __group__ = __groups__[__key__] = { parent: __obj__.parent, geometry: __obj__.geometry, material: __obj__.material, meshes: [] };\n' +
      '      __group__.meshes.push(__obj__);\n' +
      '    });\n' +
      '    const __batches__ = [];\n' +
      '    const __tmpMatrix__ = new __Matrix4Ctor__();\n' +
      '    for (const __k__ in __groups__) {\n' +
      '      const __group__ = __groups__[__k__];\n' +
      '      if (!__group__ || __group__.meshes.length < 2) continue;\n' +
      '      const __inst__ = new __InstancedMeshCtor__(__group__.geometry, __group__.material, __group__.meshes.length);\n' +
      '      __inst__.userData = __inst__.userData || {};\n' +
      '      __inst__.userData.semanticIds = [];\n' +
      '      __inst__.userData.originalObjects = [];\n' +
      '      __inst__.frustumCulled = false;\n' +
      '      for (let __i__ = 0; __i__ < __group__.meshes.length; __i__++) {\n' +
      '        const __mesh__ = __group__.meshes[__i__];\n' +
      '        __mesh__.updateMatrix();\n' +
      '        __inst__.setMatrixAt(__i__, __mesh__.matrix);\n' +
      '        __inst__.userData.semanticIds[__i__] = __mesh__.userData && __mesh__.userData.semanticId != null ? __mesh__.userData.semanticId : (__mesh__.name || null);\n' +
      '        __inst__.userData.originalObjects[__i__] = __mesh__;\n' +
      '      }\n' +
      '      __inst__.instanceMatrix.needsUpdate = true;\n' +
      '      __group__.parent.add(__inst__);\n' +
      '      for (let __r__ = 0; __r__ < __group__.meshes.length; __r__++) __group__.parent.remove(__group__.meshes[__r__]);\n' +
      '      __batches__.push({ parent: __group__.parent, inst: __inst__, meshes: __group__.meshes });\n' +
      '    }\n' +
      '    if (!__batches__.length) return null;\n' +
      '    return { batches: __batches__, tmpMatrix: __tmpMatrix__ };\n' +
      '  })();\n' +
      '  if (!' + stateName + ' || !__earlWorld__ || typeof __earlWorld__.update !== "function") return __earlWorld__;\n' +
      '  const __earlPrevUpdate__ = __earlWorld__.update;\n' +
      '  __earlWorld__.update = function() {\n' +
      '    const __result__ = __earlPrevUpdate__.apply(this, arguments);\n' +
      '    const __batches__ = ' + stateName + '.batches;\n' +
      '    for (let __bi__ = 0; __bi__ < __batches__.length; __bi__++) {\n' +
      '      const __batch__ = __batches__[__bi__];\n' +
      '      for (let __i__ = 0; __i__ < __batch__.meshes.length; __i__++) {\n' +
      '        const __mesh__ = __batch__.meshes[__i__];\n' +
      '        __mesh__.updateMatrix();\n' +
      '        __batch__.inst.setMatrixAt(__i__, __mesh__.matrix);\n' +
      '      }\n' +
      '      __batch__.inst.instanceMatrix.needsUpdate = true;\n' +
      '    }\n' +
      '    return __result__;\n' +
      '  };\n' +
      '  return __earlWorld__;\n' +
      '}\n';
  }

  for (const entry of Object.entries(files)) {
    const path = entry[0];
    const src = entry[1];
    if (typeof src !== 'string') continue;
    if (!/\.(js|mjs|ts)$/.test(path)) continue;
    if (/(^|\/)(package|build|dist|coverage|test|tests|spec|sdk)(\/|$)/i.test(path)) continue;
    const parsed = parseCreateWorld(src);
    if (!parsed) continue;
    const wrapperTemplate = makeWrapper(parsed.threeParam, parsed.sceneParam);
    const wrapper = wrapperTemplate.replace('/*__EARL_ORIGINAL_BODY__*/', parsed.body);
    const next = src.slice(0, parsed.start) + wrapper + src.slice(parsed.end);
    if (next !== src) changed.push({ path: path, content: next });
  }

  return {
    files: changed,
    notes: changed.length ? 'Wrapped eligible createWorld factories with conservative runtime sibling-mesh instancing that preserves detached original objects for update references and copies local matrices into instance slots.' : 'No eligible exported createWorld(THREE, scene) factory modules found for conservative instancing.'
  };
}
